function el(){const n={style:{opacity:''},children:[],classList:{add(){},remove(){},toggle(){}},appendChild(child){this.children.push(child);return child;},insertBefore(child){return this.appendChild(child);},get firstChild(){return this.children[0]||el();},animate(frames){const last=frames[frames.length-1];return {finished:Promise.resolve(),cancel(){},commitStyles:()=>{for(const key of ['transform','opacity','backgroundColor'])if(last[key]!==undefined)n.style[key]=last[key];}};}};nodes.push(n);return n;}
function boot(){const c={setTimeout(){return 0;},Core:{speed:1},Lisa:{make:el},document:{createElement:el,body:el()}};c.window=c;vm.createContext(c);for(const f of ['data.js','lessons_data.js','lessons_expansion_data.js','lessons_expansion2_data.js','lessons_art.js','lessons_history_art.js','lessons_expansion_art.js','lessons_expansion2_art.js'])vm.runInContext(read('app/js/'+f),c,{filename:f});return c;}
test('full registry adds exact eight authored lessons after all original eleven',()=>{const c=boot();assert.equal(c.LESSON_DATA.order.length,19);assert.deepEqual(JSON.parse(JSON.stringify(c.LESSON_DATA.order.slice(-8))),EXPECTED.order);for(const id of EXPECTED.order)assert.deepEqual(JSON.parse(JSON.stringify(c.LESSON_DATA.lessons[id])),EXPECTED.lessons[id]);});
test('copy rows and generated RU EN values exactly match approved text; target media preexists',()=>{const c=boot(),rows=read('content/ui.tsv').split(/\r?\n/).filter(Boolean);for(const [key,ru,en] of COPY)for(const [lang,text] of [['ru',ru],['en',en]]){assert.ok(rows.includes([key,lang,text].join('\t')));assert.equal(c.GAME_DATA.ui[lang][key],text);}for(const def of Object.values(EXPECTED.lessons)){assert.ok(c.GAME_DATA.items[def.word]);for(const lang of ['pt','en','de'])for(const suffix of ['', '_q'])assert.ok(fs.existsSync(path.join(root,'app/audio',lang,def.word+suffix+'.ogg')));}});
test('exact art and CSS author bytes are installed and loaded in correct order',()=>{for(const [file,hash] of Object.entries(AUTHOR))assert.equal(sha(file),hash,file);const index=read('app/index.html');for(const src of ['js/lessons_expansion_data.js','js/lessons_expansion_art.js','css/expansion.css','js/lessons_expansion2_data.js','js/lessons_expansion2_art.js','css/expansion2.css'])assert.ok(index.includes(src));assert.ok(index.indexOf('js/lessons_expansion_data.js')>index.indexOf('js/lessons_data.js'));assert.ok(index.indexOf('js/lessons_expansion_art.js')>index.indexOf('js/lessons_history_art.js'));});
test('each authored beat animation and prompt tile executes against real stage API',async()=>{const c=boot(),flow={onKill(){},wait:async()=>{}};for(const id of EXPECTED.order){const d=EXPECTED.lessons[id],S=c.LessonArt.stage(el(),flow,{}),scene=c.LessonArt.scenes[d.scene](S);assert.ok(scene.promptBox);for(const beat of d.beats){assert.ok(c.GAME_DATA.ui.ru[beat.line]);for(const name of [].concat(beat.anim||[])){assert.equal(typeof scene.act[name],'function',id+':'+name);await scene.act[name]();}for(const choice of beat.prompt?.choices||[]){const tile=scene.tile(choice.tile,220);assert.ok(tile&&tile.className.includes('ls-tile-in'));}if(beat.prompt?.q)assert.ok(c.GAME_DATA.ui.en[beat.prompt.q]);}}});
test('original eleven data art first expansion all audio and prior path repairs remain byte exact',()=>{for(const [file,hash] of Object.entries(PRESERVE))assert.equal(sha(file),hash,file);});

test('unequal apple pieces retain authored separated offsets after emphasis',async()=>{const c=boot(),S=c.LessonArt.stage(el(),{onKill(){},wait:async()=>{}},{});nodes.length=0;const scene=c.LessonArt.scenes.x_halves(S);await scene.act.cutSide();const find=cls=>nodes.find(n=>(n.className||'').split(' ').includes(cls));assert.equal(find('ls-x-big').style.transform,S.T(-40,0));assert.equal(find('ls-x-small').style.transform,S.T(40,0));});
test('frog retains lily-pad destination through jump emphasis and recap',async()=>{const c=boot(),S=c.LessonArt.stage(el(),{onKill(){},wait:async()=>{}},{});nodes.length=0;const scene=c.LessonArt.scenes.x_frog(S);await scene.act.jump();const frog=nodes.find(n=>(n.className||'').split(' ').includes('ls-x2-frog'));assert.equal(frog.style.transform,S.T(220,-230));await scene.act.recap();assert.equal(frog.style.transform,S.T(220,-230));});

test('rainbow sun placement is disjoint from authored navigation control bounds',()=>{const c=boot(),S=c.LessonArt.stage(el(),{onKill(){},wait:async()=>{}},{});nodes.length=0;c.LessonArt.scenes.x_rainbow(S);const sun=nodes.find(n=>(n.className||'').split(' ').includes('ls-x-sun'));assert.ok(sun);const rect={x:parseFloat(sun.style.left)*10,y:parseFloat(sun.style.top)*10,w:parseFloat(sun.style.width)*10,h:parseFloat(sun.style.height)*10},nav={x:0,y:0,w:210,h:105};const overlap=Math.max(0,Math.min(rect.x+rect.w,nav.x+nav.w)-Math.max(rect.x,nav.x))*Math.max(0,Math.min(rect.y+rect.h,nav.y+nav.h)-Math.max(rect.y,nav.y));assert.equal(overlap,0,JSON.stringify(rect));assert.deepEqual(rect,{x:40,y:230,w:160,h:160});});
